//pages/public/actualites.jsx

import { useEffect, useState } from "react";
import { Link, useSearchParams } from "react-router-dom";
import api from "@/utils/api";
import jsPDF from "jspdf";
import html2canvas from "html2canvas";

export default function Actualites() {
  const [searchParams, setSearchParams] = useSearchParams();
  const [actualites, setActualites] = useState([]);
  const [page, setPage] = useState(parseInt(searchParams.get("page")) || 1);
  const [search, setSearch] = useState(searchParams.get("search") || "");
  const [sortOrder, setSortOrder] = useState(searchParams.get("sort") || "desc");
  const [month, setMonth] = useState(searchParams.get("month") || "");
  const [year, setYear] = useState(searchParams.get("year") || "");
  const [totalPages, setTotalPages] = useState(1);
  const [anneesDispo, setAnneesDispo] = useState([]);
  const [categorie, setCategorie] = useState(searchParams.get("categorie") || "");
  const limit = 6;

  useEffect(() => {
    const fetchActualites = async () => {
      try {
        const res = await api.get("/actualites", {
          params: {
            page,
            limit,
            search,
            sort: sortOrder,
            ...(month && { month }),
            ...(year && { year }),
            ...(categorie && { categorie })
          },
        });
        const data = res.data;

        setActualites(Array.isArray(data.data) ? data.data : []);
        setTotalPages(Math.ceil(data.total / data.limit));
      } catch (err) {
        console.error("Erreur de chargement des actualités :", err);
        setActualites([]);
        alert("Erreur de chargement des actualités");
      }
    };
    fetchActualites();
  }, [page, search, sortOrder, month, year, categorie]);

  useEffect(() => {
    api.get("/actualites/annees")
      .then((res) => setAnneesDispo(res.data))
      .catch(() => setAnneesDispo([2025, 2024, 2023]));
  }, []);

  const handleSearch = (e) => {
    e.preventDefault();
    setPage(1);
    setSearchParams({ page: 1, search, sort: sortOrder, month, year, categorie });
  };

  const handleExportPDF = async () => {
    const input = document.querySelector(".grid");
    if (!input) return;
    const canvas = await html2canvas(input, { scale: 2 });
    const imgData = canvas.toDataURL("image/png");
    const pdf = new jsPDF("p", "mm", "a4");
    const pageWidth = pdf.internal.pageSize.getWidth();
    const ratio = pageWidth / canvas.width;
    pdf.addImage(imgData, "PNG", 0, 10, pageWidth, canvas.height * ratio);
    pdf.save("actualites.pdf");
  };

  return (
    <div className="max-w-6xl mx-auto px-4 pt-20 pb-28 relative">
      <h1 className="text-3xl font-bold text-red-600 mb-6">Actualités</h1>
      <div className="flex justify-end mb-4">
        <button
          onClick={handleExportPDF}
          className="bg-gray-200 text-sm px-4 py-2 rounded hover:bg-gray-300"
        >
          Exporter la liste en PDF
        </button>
      </div>

      {/* Recherche et filtres */}
      <form onSubmit={handleSearch} className="mb-6 flex flex-col md:flex-row flex-wrap gap-4 md:items-center">
        <input
          type="text"
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          placeholder="Rechercher un titre..."
          className="border p-2 rounded w-full md:w-1/3"
        />
        <select
          value={sortOrder}
          onChange={(e) => {
            setSortOrder(e.target.value);
            setPage(1);
          }}
          className="border p-2 rounded text-sm md:w-40"
        >
          <option value="desc">Plus récentes</option>
          <option value="asc">Plus anciennes</option>
        </select>
        <select
          value={month}
          onChange={(e) => setMonth(e.target.value)}
          className="border p-2 rounded text-sm md:w-28"
        >
          <option value="">Mois</option>
          {[...Array(12)].map((_, i) => (
            <option key={i + 1} value={i + 1}>{i + 1}</option>
          ))}
        </select>
        <select
          value={year}
          onChange={(e) => setYear(e.target.value)}
          className="border p-2 rounded text-sm md:w-28"
        >
          <option value="">Année</option>
          {anneesDispo.map((y) => (
            <option key={y} value={y}>{y}</option>
          ))}
        </select>
        <select
          value={categorie}
          onChange={(e) => setCategorie(e.target.value)}
          className="border p-2 rounded text-sm md:w-40"
        >
          <option value="">Toutes les catégories</option>
          <option value="Annonce">Annonce</option>
          <option value="Événement">Événement</option>
          <option value="Projet">Projet</option>
        </select>
        <button type="submit" className="bg-red-600 text-white px-4 py-2 rounded hover:bg-red-700">
          Rechercher
        </button>
      </form>

      {/* Liste des actualités */}
      <div className="grid sm:grid-cols-2 md:grid-cols-3 gap-6">
        {actualites.length === 0 && (
          <p className="text-center text-gray-500 col-span-full">Aucune actualité trouvée.</p>
        )}
        {actualites.map((actu) => (
          <div
            key={actu.id}
            className="bg-white rounded-xl shadow hover:shadow-md transition-all duration-300 p-4 flex flex-col"
          >
            {actu.image && (
              <img
                src={actu.image?.startsWith("http") ? actu.image : `https://cdotchad.com/api/${actu.image}`}
                alt={actu.titre}
                className="h-40 w-full object-cover rounded mb-3"
              />
            )}
            <span className="text-xs text-red-500 font-semibold uppercase mb-1">
              {actu.categorie || "Non classée"}
            </span>
            <h3 className="font-bold text-base mb-1 text-gray-800">{actu.titre}</h3>
            <p className="text-xs text-gray-500 mb-2">
              {new Date(actu.date_publication).toLocaleDateString("fr-FR", {
                weekday: "short",
                year: "numeric",
                month: "long",
                day: "numeric",
              })}
            </p>
            <div className="text-sm text-gray-700 flex-1 mb-3 line-clamp-4">
              {actu.resume ? (
                <span
                  dangerouslySetInnerHTML={{
                    __html: actu.resume,
                  }}
                />
              ) : (
                <span>
                  {actu.contenu?.replace(/<[^>]+>/g, "").slice(0, 150)}...
                </span>
              )}
            </div>
            <Link
              to={`/actualites/${actu.id}`}
              className="text-red-600 text-sm font-medium hover:underline mt-auto"
            >
              Lire la suite →
            </Link>
          </div>
        ))}
      </div>

      {/* Pagination */}
      <div className="flex justify-center mt-8 gap-4">
        <button
          onClick={() => {
            const newPage = Math.max(page - 1, 1);
            setPage(newPage);
            setSearchParams({ page: newPage, search, sort: sortOrder, month, year, categorie });
          }}
          disabled={page <= 1}
          className="px-4 py-1 rounded border text-sm disabled:opacity-50"
        >
          ← Précédent
        </button>
        <span className="text-sm text-gray-700">Page {page} / {totalPages}</span>
        <button
          onClick={() => {
            const newPage = page + 1;
            setPage(newPage);
            setSearchParams({ page: newPage, search, sort: sortOrder, month, year, categorie });
          }}
          disabled={page >= totalPages}
          className="px-4 py-1 rounded border text-sm disabled:opacity-50"
        >
          Suivant →
        </button>
      </div>
    </div>
  );
}
