import { useEffect, useState } from "react";
import {
  ajouterOffre,
  modifierOffre,
  supprimerOffre,
} from "@/utils/adminApi";
import api from "@/utils/api";
import { toast } from "react-toastify";
import { Pencil, Trash2, PlusCircle } from "lucide-react";

export default function AdminOffres() {
  const [offres, setOffres] = useState([]);
  const [isEditing, setIsEditing] = useState(false);
  const [formData, setFormData] = useState({
    titre: "",
    description: "",
    lieu: "",
    type_contrat: "",
    employeur: "",
  });
  const [editId, setEditId] = useState(null);

  const chargerOffres = async () => {
    try {
      const res = await api.get("/offres");
      setOffres(res.data);
    } catch (error) {
      toast.error("Erreur de chargement des offres");
    }
  };

  useEffect(() => {
    chargerOffres();
  }, []);

  const handleChange = (e) => {
    setFormData((prev) => ({
      ...prev,
      [e.target.name]: e.target.value,
    }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      const formToSend = new FormData();
      for (let key in formData) {
        formToSend.append(key, formData[key]);
      }

      if (isEditing && editId) {
        await modifierOffre(editId, formToSend);
        toast.success("Offre mise à jour");
      } else {
        await ajouterOffre(formToSend);
        toast.success("Offre ajoutée");
      }

      setFormData({
        titre: "",
        description: "",
        lieu: "",
        type_contrat: "",
        employeur: "",
      });
      setIsEditing(false);
      setEditId(null);
      chargerOffres();
    } catch (err) {
      toast.error("Erreur lors de l'enregistrement");
    }
  };

  const handleEdit = (offre) => {
    setFormData(offre);
    setEditId(offre.id);
    setIsEditing(true);
  };

  const handleDelete = async (id) => {
    if (window.confirm("Voulez-vous vraiment supprimer cette offre ?")) {
      try {
        await supprimerOffre(id);
        toast.success("Offre supprimée");
        chargerOffres();
      } catch (err) {
        toast.error("Erreur lors de la suppression");
      }
    }
  };

  return (
    <div className="max-w-5xl mx-auto px-6 py-8">
      <h1 className="text-2xl font-bold mb-6">
        {isEditing ? "Modifier une offre" : "Ajouter une offre"}
      </h1>

      <form
        onSubmit={handleSubmit}
        className="grid grid-cols-1 md:grid-cols-2 gap-4 bg-white p-4 rounded shadow mb-8"
      >
        <input
          type="text"
          name="titre"
          value={formData.titre}
          onChange={handleChange}
          placeholder="Titre de l'offre"
          required
          className="border rounded p-2"
        />
        <input
          type="text"
          name="lieu"
          value={formData.lieu}
          onChange={handleChange}
          placeholder="Lieu"
          required
          className="border rounded p-2"
        />
        <input
          type="text"
          name="type_contrat"
          value={formData.type_contrat}
          onChange={handleChange}
          placeholder="Type de contrat"
          required
          className="border rounded p-2"
        />
        <input
          type="text"
          name="employeur"
          value={formData.employeur}
          onChange={handleChange}
          placeholder="Employeur"
          required
          className="border rounded p-2"
        />
        <textarea
          name="description"
          value={formData.description}
          onChange={handleChange}
          placeholder="Description"
          rows={3}
          className="md:col-span-2 border rounded p-2"
        />
        <button
          type="submit"
          className="md:col-span-2 bg-red-600 text-white px-4 py-2 rounded hover:bg-red-700 flex items-center gap-2 justify-center"
        >
          <PlusCircle size={18} />
          {isEditing ? "Mettre à jour" : "Ajouter l'offre"}
        </button>
      </form>

      <h2 className="text-xl font-semibold mb-4">Liste des Offres</h2>
      <div className="grid gap-4">
        {offres.map((offre) => (
          <div
            key={offre.id}
            className="bg-white shadow rounded p-4 flex justify-between items-start"
          >
            <div>
              <h3 className="text-lg font-bold">{offre.titre}</h3>
              <p className="text-sm text-gray-600">{offre.lieu}</p>
              <p className="text-sm">Contrat: {offre.type_contrat}</p>
              <p className="text-sm">Employeur: {offre.employeur}</p>
            </div>
            <div className="flex gap-2">
              <button
                onClick={() => handleEdit(offre)}
                className="p-2 rounded hover:bg-gray-100"
                title="Modifier"
              >
                <Pencil size={18} />
              </button>
              <button
                onClick={() => handleDelete(offre.id)}
                className="p-2 rounded hover:bg-red-100"
                title="Supprimer"
              >
                <Trash2 size={18} className="text-red-600" />
              </button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
