// src/routes/public/HomeRoutes.jsx
import Home from "@/pages/public/Home.jsx";
import Presentation from "@/pages/public/Presentation";
import Services from "@/pages/public/Services";
import Objectifs from "@/components/HomeObjectifs";
import Activites from "@/components/HomeActivites";
import PourquoiNous from "@/components/HomePourquoi";
import { HomeIcon, Info, Wrench, Target, Activity, HelpCircle } from "lucide-react";

const homeRoutes = [
  {
    path: "/",
    name: "Accueil", // ✅ Ajout obligatoire pour l'afficher dans le menu
    element: <Home />,
    icon: <HomeIcon className="w-4 h-4" />,
  },
  {
    path: "/presentation",
    name: "Présentation",
    element: <Presentation />,
    icon: <Info className="w-4 h-4" />,
  },
  {
    path: "/services",
    name: "Nos Services",
    element: <Services />,
    icon: <Wrench className="w-4 h-4" />,
  },
  {
    path: "/objectifs",
    name: "Nos Objectifs",
    element: <Objectifs />,
    icon: <Target className="w-4 h-4" />,
  },
  {
    path: "/activites",
    name: "Nos Activités",
    element: <Activites />,
    icon: <Activity className="w-4 h-4" />,
  },
  {
    path: "/pourquoi",
    name: "Pourquoi nous choisir ?",
    element: <PourquoiNous />,
    icon: <HelpCircle className="w-4 h-4" />,
  },
];

export default homeRoutes;
